export type FieldShapes = { subject: FieldShape; catalog: FieldShape; title: FieldShape }
export type FileUsage = { name: string; bytes: number; modifiedAt: string | null }
export type Finding = { code: FindingCode; severity: Severity; field: Field; count: number; 
/**
 * `count / importable`; 0.0 for dataset-level checks with no row count.
 */
rate: number; examples: Samples<Sample> }
/**
 * Declared in report order: warnings, then notes. `checks` and `findings`
 * follow this order.
 */
export type FindingCode = "catalog_has_subject_prefix" | "subject_has_number" | "catalog_numeric_coerced" | "catalog_no_digits" | "catalog_has_whitespace" | "catalog_too_long" | "catalog_low_cardinality" | "subject_too_long" | "subject_high_cardinality" | "title_no_letters" | "title_too_long" | "title_repeats_code" | "title_short" | "catalog_short" | "subject_lowercase" | "title_mixed_case" | "encoding_damage" | "inner_whitespace_runs"
export type ImportRequest = { path: string; 
/**
 * Falls back to the filename when null/blank.
 */
displayName: string | null; 
/**
 * Optional row cap; `None` means import every row.
 */
limit: number | null; 
/**
 * Confirmed by the user from `inspect_csv`'s encoding report.
 */
encoding: TextEncoding; 
/**
 * The mapping `validate_import` returned; re-checked against the header.
 */
mapping: ColumnMap }
/**
 * Response from `import_csv`: the dataset has been queued and is already
 * streaming rows in. The frontend polls `list_datasets` from here.
 */
export type ImportStarted = { datasetId: string; sourceFileId: number }
export type InputProfile = { version: number; 
/**
 * Data records seen, excluding the header.
 */
rows: number; 
/**
 * Rows with subject, catalog, and title all non-empty after trim.
 */
importable: number; 
/**
 * Rows with at least one empty required field, by which field was empty.
 * A row missing two fields counts in both.
 */
skipped: SkipCounts; columns: MappedColumns; fields: FieldShapes; 
/**
 * Every check's raw count, whether or not it crossed its threshold.
 */
checks: CheckCount[]; 
/**
 * Checks that crossed their threshold, warnings first.
 */
findings: Finding[]; 
/**
 * Assembled model-input strings, spread across the file, distinct.
 */
samples: Sample[] }
export type Inspection = { sizeBytes: number; 
/**
 * Data records, excluding the header.
 */
rows: number; headerFields: number; encoding: EncodingReport; 
/**
 * Records whose field count differs from the header's. Import requires
 * zero.
 */
raggedRows: Samples<RaggedRow> }
/**
 * A field that isn't valid UTF-8, rendered under each legacy candidate so
 * the user can pick the one that reads correctly.
 */
export type InvalidField = { row: number; column: string; windows1252: string; macRoman: string }
/**
 * How many of the dataset's courses have a result for one model. Same units
 * as `get_classification_coverage`, so the card can switch between them.
 */
export type LevelProgress = { digitLevel: number; done: number; total: number }
export type ListCoursesRequest = { datasetId: string; 
/**
 * Optional model id for the joined classification + probability columns.
 * `None` means the joined columns come back as `null`.
 */
modelId: number | null; 
/**
 * Key-set cursor: include rows with `row_index >= cursor`. `None` (and 0)
 * mean "from the start". The frontend hands back the row index of the
 * last row of a page + 1 to advance. Replaces `OFFSET` because `DuckDB`'s
 * `TopN` plan for `ORDER BY row_index LIMIT n OFFSET m` scans the whole
 * partition; the range predicate lets the scan skip to the cursor.
 */
cursor: number | null; limit: number }
export type MappedColumns = { subject: ColumnStats; catalog: ColumnStats; title: ColumnStats }
/**
 * A frontend-handled menu command. The serde name is the native menu item id.
 */
export type MenuAction = "about" | "preferences" | "import_csv" | "export_results" | "start_classification" | "stop_classification" | "toggle_sidebar" | "toggle_command_palette"
/**
 * Emitted when a native menu item (or its accelerator) fires.
 */
export type MenuActionTriggered = { action: MenuAction }
/**
 * Per-file download progress. `received`/`total` are bytes; `bytes_per_sec`
 * is measured over the emission window (EPI-65). The frontend derives
 * percentages.
 */
export type ModelDownloadProgress = { digitLevel: number; file: string; received: number; total: number; bytesPerSec: number }
export type ModelStatus = { digitLevel: number; displayName: string; hfRepo: string; revision: string; filesTotal: number; 
/**
 * Files on disk with the manifest's exact size. Full sha256 verification
 * happens during download, not on status polls.
 */
filesPresent: number; 
/**
 * The files on disk were downloaded for an earlier release's revision
 * of this model (#202). It can't be loaded until downloaded again,
 * even when `files_present` says every file is there.
 */
updateRequired: boolean; totalBytes: number; loaded: boolean; loading: boolean; 
/**
 * Whether a download is in flight app-wide (same value on every row).
 * This — not any component-local pending flag — gates the Download
 * button (EPI-74).
 */
downloading: boolean; 
/**
 * This level's last-known download position, when a download has
 * touched it. Hydrates a freshly-mounted progress bar.
 */
download: DownloadSnapshot | null }
/**
 * Coarse "something about model state changed" signal — emitted after a file
 * finishes downloading, a load starts/completes, or either fails. The
 * frontend responds by refetching `models_status`.
 */
export type ModelsStateChanged = Record<string, never>
/**
 * The startup phases, in order. The boot screen titles each one, so a
 * phase names only work that is really happening: `UpgradingSchema` is
 * entered only while a schema migration runs.
 */
export type Phase = "MigratingData" | "OpeningDatabase" | 
/**
 * The pre-upgrade copy of the database (#204). Set by `AppDb::open_at`,
 * not by a step.
 */
"BackingUp" | "UpgradingSchema" | "LoadingRuntime"
/**
 * Which cached classifications [`storage_prune`] removes.
 */
export type PruneScope = 
/**
 * Results of model revisions this build no longer ships. Nothing in the
 * app can show or export them.
 */
"superseded_models" | 
/**
 * Results for inputs no dataset contains. They would be recomputed if
 * the same courses were imported again.
 */
"unreferenced"
export type RaggedRow = { row: number; fields: number }
/**
 * Row granularity of the export (EPI-78).
 */
export type RowMode = 
/**
 * One output row per input row (source fidelity, mergeable back onto
 * the original file).
 */
"all" | 
/**
 * One output row per distinct classified input (`content_hash`).
 * Duplicate inputs share one cached result by construction; the
 * representative row is the first occurrence (lowest `row_index`).
 */
"unique"
/**
 * Per-pack download progress, mirroring `models::ModelDownloadProgress`.
 */
export type RuntimeDownloadProgress = { packId: string; received: number; total: number; bytesPerSec: number }
export type RuntimePackStatus = { id: string; displayName: string; 
/**
 * EPs the pack claims to carry (manifest metadata; empty = libs pack).
 */
eps: string[]; sizeBytes: number; installed: boolean; 
/**
 * Whether this is the pack the running process loaded (always false for
 * libs packs — they are preloaded next to a runtime pack, not loaded as
 * one).
 */
active: boolean; 
/**
 * Companion libs pack id, when this runtime pack has one (EPI-84).
 */
libs: string | null }
/**
 * Coarse "runtime pack state changed" signal — emitted when a pack install
 * finishes or fails; the frontend refetches `runtime_status`.
 */
export type RuntimeStateChanged = Record<string, never>
export type RuntimeStatus = { ortVersion: string; 
/**
 * Pack the running process loaded (fixed until relaunch).
 */
activePackId: string; 
/**
 * EP the loaded models actually run on; `None` until models load.
 */
resolvedEp: string | null; 
/**
 * Platform EPs in the shape the settings priority list stores, for the
 * settings UI to render reorderable rows without hardcoding.
 */
platformDefaultPriority: EpKind[]; packs: RuntimePackStatus[]; 
/**
 * Startup runtime conditions worth a warning in Settings (EPI-87):
 * damaged-pack fallback, missing CUDA directory, failed preloads.
 */
notices: string[] }
export type RuntimeUsage = { ortVersion: string; 
/**
 * Whether this is the version the app loads packs from.
 */
current: boolean; path: string; bytes: number }
export type Sample = { row: number; input: string }
/**
 * A count of occurrences plus the first few examples.
 */
export type Samples<T> = { count: number; first: T[] }
/**
 * The semantic `--ui-*` tokens. Field names render to the token suffix; the
 * applier prepends `--ui-` (e.g. `bg_muted` -> `--ui-bg-muted`).
 */
export type SemanticTokens = { bg?: string | null; "bg-muted"?: string | null; "bg-elevated"?: string | null; "bg-accented"?: string | null; "bg-inverted"?: string | null; text?: string | null; "text-muted"?: string | null; "text-dimmed"?: string | null; "text-toned"?: string | null; "text-highlighted"?: string | null; "text-inverted"?: string | null; border?: string | null; "border-muted"?: string | null; "border-accented"?: string | null; "border-inverted"?: string | null; primary?: string | null; secondary?: string | null; success?: string | null; info?: string | null; warning?: string | null; error?: string | null; radius?: string | null }
/**
 * General application settings. `activeTheme` references a theme by id; design
 * tokens themselves live in `themes/*.json`, not here.
 */
export type Settings = { activeTheme: string; 
/**
 * Execution-provider priority for inference (EPI-73), most preferred
 * first. `cpu` is a list entry meaning "allowed as fallback" — the one
 * mechanism, no separate GPU toggle. Reordering takes effect on the
 * next model load; switching *packs* (cpu↔cuda dylib) needs a relaunch.
 * `serde(default)` keeps pre-EPI-73 settings.json files parsing under
 * `deny_unknown_fields`.
 */
executionProviders?: EpKind[]; 
/**
 * Cap on ORT's intra-op CPU threads during inference (EPI-83).
 * `0` = auto (ORT default: all physical cores); any value below 1 or
 * above the machine's cores also behaves as auto — clamp semantics,
 * no error states. Applied at session build; rides `reload_models`.
 */
maxCpuThreads?: number; 
/**
 * Directory holding CUDA/cuDNN libraries to preload at startup (EPI-84)
 * — for users whose CUDA lives in a conda env or pip venv
 * (`site-packages/nvidia`) instead of a system install. Takes precedence
 * over the downloadable support-libs pack; changing it needs a relaunch
 * (preload is process-lifetime).
 */
cudaLibraryDir?: string | null; 
/**
 * Runtime pack the user explicitly activated in Settings → Compute
 * (EPI-94). Checked before the EP-priority scan at startup, so an
 * explicit choice can never be shadowed by manifest order. `None` — or a
 * pack that is no longer installed — falls back to the scan, whose
 * terminal fallback is the bundled CPU pack. Switching packs requires a
 * relaunch (ONNX Runtime is init-once).
 */
preferredPack?: string | null }
export type Severity = "warning" | "info"
export type SkipCounts = { total: number; subject: number; catalog: number; title: number }
export type SkippedRow = { row: number; 
/**
 * Headers of the required columns that were empty.
 */
missing: string[] }
export type StorageStatus = { 
/**
 * The data folder everything below lives in (except the `CoreML` cache).
 */
dataDir: string; database: DatabaseUsage; cache: CacheUsage; models: DirUsage; 
/**
 * Downloaded runtime packs, one entry per ONNX Runtime version folder.
 */
runtimes: RuntimeUsage[]; 
/**
 * Compiled `CoreML` models; `None` off macOS, where none are made.
 */
coremlCache: DirUsage | null; logs: DirUsage; 
/**
 * WALs set aside after a failed replay, oldest first.
 */
setAsideWals: FileUsage[]; 
/**
 * Pre-upgrade database backups. Each is as large as the database was.
 */
databaseBackups: FileUsage[]; 
/**
 * Why prune and compact can't start right now, or `None` when they can.
 */
busy: string | null }
/**
 * Text encoding of a source CSV. `Utf8` covers files with or without a BOM;
 * the legacy variants are the two single-byte codepages Excel writes for
 * plain "CSV": Windows-1252 on Windows, Mac Roman on macOS. Both are ASCII
 * supersets, so CSV structure (delimiters, quotes, newlines) parses
 * identically under every variant.
 */
export type TextEncoding = "utf8" | "windows1252" | "macRoman"
/**
 * A full theme. `id` is the filename stem (set after load), never read from the
 * file body — `deny_unknown_fields` rejects an `id` key in the JSON.
 */
export type Theme = { name: string; colorScheme: ColorScheme; font?: string | null; tokens?: SemanticTokens; colors?: ColorRamps }
/**
 * Lightweight listing entry (no token payload) for the theme registry.
 */
export type ThemeSummary = { id: string; name: string; colorScheme: ColorScheme }
export type Validation = { headers: string[]; sampleRows: string[][]; 
/**
 * Auto-detected from header aliases. `import_csv` takes it back verbatim.
 */
mapping: ColumnMap; 
/**
 * Data records, excluding the header.
 */
rows: number; 
/**
 * Records with subject, catalog, and title all non-empty — what import
 * will ingest.
 */
importable: number; skipped: Samples<SkippedRow>; 
/**
 * Cells longer than the per-field cap; import truncates them.
 */
truncatedFields: number; 
/**
 * `profile.columns`, kept here for the dialog's column grid.
 */
columns: MappedColumns; 
/**
 * Field shapes, checks, findings, and sample model inputs.
 */
profile: InputProfile }
export type ValueCount = { value: string; count: number }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
